#include <stdio.h>

static long long prefix[100001];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        long long value;
        scanf("%lld", &value);
        prefix[i] = prefix[i - 1] + value;
    }
    int q;
    if (scanf("%d", &q) != 1) {
        return 0;
    }
    for (int k = 0; k < q; k++) {
        int l, r;
        if (scanf("%d %d", &l, &r) != 2) {
            break;
        }
        printf("%lld\n", prefix[r] - prefix[l - 1]);
    }
    return 0;
}

