#include <stdio.h>

static long long values[100000];

int main(void) {
    int n;
    long long limit;
    if (scanf("%d %lld", &n, &limit) != 2 || n < 1 || n > 100000) {
        return 0;
    }
    for (int i = 0; i < n; i++) {
        scanf("%lld", &values[i]);
    }
    long long sum = 0;
    int left = 0, best_len = 0, best_start = 0;
    for (int right = 0; right < n; right++) {
        sum += values[right];
        while (sum > limit) {
            sum -= values[left];
            left++;
        }
        int len = right - left + 1;
        if (len > best_len) {
            best_len = len;
            best_start = left;
        }
    }
    if (best_len == 0) {
        printf("0\n");
    } else {
        printf("%d %d\n", best_len, best_start + 1);
    }
    return 0;
}

